(function () {
  'use strict';

  function initShopLook(root) {
    if (!root || root.dataset.hgReady === '1') return;
    root.dataset.hgReady = '1';

    const pins = Array.from(root.querySelectorAll('[data-hg-look-pin]'));
    const cards = Array.from(root.querySelectorAll('[data-hg-look-card]'));
    const tabs = Array.from(root.querySelectorAll('[data-hg-look-tab]'));

    function activate(id, focusCard) {
      id = String(id);

      pins.forEach(function (pin) {
        const active = String(pin.getAttribute('data-hg-look-pin')) === id;
        pin.classList.toggle('is-active', active);
        pin.setAttribute('aria-expanded', active ? 'true' : 'false');
      });

      tabs.forEach(function (tab) {
        const active = String(tab.getAttribute('data-hg-look-tab')) === id;
        tab.classList.toggle('is-active', active);
        tab.setAttribute('aria-pressed', active ? 'true' : 'false');
      });

      cards.forEach(function (card) {
        const active = String(card.getAttribute('data-hg-look-card')) === id;
        card.hidden = !active;
        card.classList.toggle('is-active', active);
        if (active && focusCard) {
          card.setAttribute('tabindex', '-1');
          card.focus({ preventScroll: true });
        }
      });
    }

    root.addEventListener('click', function (event) {
      const pin = event.target.closest('[data-hg-look-pin]');
      if (pin) {
        event.preventDefault();
        activate(pin.getAttribute('data-hg-look-pin'), false);
        return;
      }

      const tab = event.target.closest('[data-hg-look-tab]');
      if (tab) {
        event.preventDefault();
        activate(tab.getAttribute('data-hg-look-tab'), false);
      }
    });

    pins.forEach(function (pin, index) {
      pin.addEventListener('keydown', function (event) {
        if (!['ArrowRight', 'ArrowLeft', 'ArrowDown', 'ArrowUp'].includes(event.key)) return;
        event.preventDefault();
        const direction = ['ArrowRight', 'ArrowDown'].includes(event.key) ? 1 : -1;
        const next = pins[(index + direction + pins.length) % pins.length];
        next.focus();
        activate(next.getAttribute('data-hg-look-pin'), false);
      });
    });
  }

  function boot() {
    document.querySelectorAll('[data-hg-hotspot-look]').forEach(initShopLook);
  }

  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', boot, { once: true });
  } else {
    boot();
  }
})();
